using System;using System.IO;using System.Linq;using HdrPilot;
class AddonTests {
 static int count;static void Check(bool value,string name){if(!value)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}
 static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Core.Data=Path.Combine(root,"data");Core.Init();var g=new Game{Id="manual",Name="CONTROL Resonant",Root=root,Exe=Path.Combine(root,"Game.exe")};File.Copy(typeof(Core).Assembly.Location,g.Exe);string rr=Path.Combine(root,"renodx-control-rr.addon64"),other=Path.Combine(root,"renodx-other.addon64");File.Copy(g.Exe,rr);File.Copy(g.Exe,other);File.Copy(g.Exe,Path.Combine(root,MfgAddon.Name));var items=ModInventory.Scan(g);Check(items.Count(i=>i.Id=="addon")==2&&!RenoDx.HasHdrAddon(g),"manual add-ons do not imply HDR installed");Check(items.Count(i=>i.Id=="mfg")==1,"MFG remains independent");var item=items.Single(i=>i.File==rr);ModUpdates.Check(item);Check(item.Status=="Nexus Mods: assisted update"&&!item.UpdateAvailable,"Nexus status does not invent latest version");string sourceFolder=Path.Combine(root,"download");Directory.CreateDirectory(sourceFolder);string source=Path.Combine(sourceFolder,Path.GetFileName(rr));File.Copy(rr,source);File.AppendAllText(source,"new payload");var plan=RenoDx.ReplaceManualAddon(g,rr,source);Check(plan.Changes.Count==1&&plan.Changes[0].Name==Path.GetFileName(rr),"update targets only exact installed file");string recovery=DlssCore.Apply(g,plan);Check(DlssCore.Hash(rr)==DlssCore.Hash(source)&&File.Exists(other),"update applied and other add-ons preserved");DlssCore.Apply(g,DlssCore.Recovery(g,Path.Combine(recovery,"transaction.json")));Check(DlssCore.Hash(rr)==DlssCore.Hash(g.Exe),"update recovery restores original add-on");bool rejected=false;try{RenoDx.ReplaceManualAddon(g,rr,other);}catch{rejected=true;}Check(rejected,"wrong replacement filename rejected");plan=ModInventory.Remove(item);recovery=DlssCore.Apply(g,plan);Check(!File.Exists(rr)&&File.Exists(other)&&File.Exists(Path.Combine(root,MfgAddon.Name)),"individual removal preserves other manual add-ons and MFG");DlssCore.Apply(g,DlssCore.Recovery(g,Path.Combine(recovery,"transaction.json")));string unpacked=NexusDownload.Extract(Path.GetFullPath(args[1]),Path.Combine(root,"unpacked"),"renodx-control-rr.addon64");Check(DlssCore.Pe64(unpacked),"actual Nexus archive validates exact RR addon");rejected=false;try{NexusDownload.Extract(Path.GetFullPath(args[1]),Path.Combine(root,"wrong"),"renodx-other.addon64");}catch{rejected=true;}Check(rejected,"wrong Nexus archive rejected");Console.WriteLine("PASS "+count+" add-on checks");return 0;}catch(Exception ex){Console.WriteLine(ex);return 1;}}
}
